    return wxGetApp().app_config != nullptr && wxGetApp().app_config->get("jusprin_shell") == "0";
}

void attach_shell(MainFrame& frame, Notebook* tabpanel, wxSizer* main_sizer)
{
    // JusPrin's splash, if startup showed one, closes when this frame is
    // first shown, where OrcaSlicer closes its own.
    close_splash_when_shown(frame);
    // Before the shell checks below, so the classic presentation gets this
    // too: JusPrin checks for its own new versions, and OrcaSlicer's check,
    // which asks OrcaSlicer's server about OrcaSlicer releases, never runs.
    // Its startup call is left to JusPrin's own schedule; Help > Check for
    // Updates checks at once and, with the shell on, shows Preferences >
    // Updates, where the result appears.
    if (wxGetApp().is_editor()) {
        Updates::update_check().attach(frame);
        // And tells JusPrin's server that this run started, once; see LaunchReport.hpp.
        Updates::report_launch();
        wxGetApp().app_update_check = [](int by_user) {
            if (by_user != 0)
                check_for_updates();
        };
        // Built-in printer and filament profiles change only with a JusPrin
        // release, so OrcaSlicer's profile server is never asked about them,
        // nor Bambu's server for its printer configuration bundle. All three
        // of OrcaSlicer's checks (profiles at startup and on switching to
        // another maker's printer, the bundle at startup) read this preference.
        if (wxGetApp().app_config != nullptr)
            wxGetApp().app_config->set_bool("sync_system_preset", false);
        // A file opened from the OS lands in the running JusPrin, and a .3mf
        // opens as a project without OrcaSlicer's "open as project or import
        // geometry?" question (architecture.md, "Opening and importing
        // files"). OrcaSlicer reads single_instance at startup before this
        // runs, so a second launch takes it from the value stored here; a
        // file opened while JusPrin runs reads it when the open request comes in.
        if (wxGetApp().app_config != nullptr) {
            wxGetApp().app_config->set_bool("single_instance", true);
            wxGetApp().app_config->set(SETTING_PROJECT_LOAD_BEHAVIOUR, OPTION_PROJECT_LOAD_BEHAVIOUR_LOAD_ALL);
            // A project keeps the printer it was saved for, also when a
            // different Bambu printer is connected: OrcaSlicer's stored "No"
            // to its "sync the printer and switch the preset?" question, so
            // it is never asked, on a file open or on reopening a saved
            // project from Home.
            wxGetApp().app_config->set_bool("sync_after_load_file_show_flag", false);
            // OrcaSlicer 2.5.0's stored "Don't remind me again" to its startup
            // offer to add back the printers a user filament preset's parent
            // listed in 2.4.2. The offer counts every preset that takes its
            // printers from its parent as made before 2.5.0. JusPrin has no
            // presets from before 2.5.0, so it would make the offer for
            // presets JusPrin just made, naming OrcaSlicer and a Help item
            // JusPrin doesn't show.
            wxGetApp().app_config->set_bool("legacy_user_filament_presets_dont_remind", true);
            // Space opens OrcaSlicer 2.5.0's Speed Dial, a palette of
            // OrcaSlicer's own commands, which JusPrin's menus leave out
            // (AppMenus). This is OrcaSlicer's preference for that key; classic
            // view's menu item still opens it.
            wxGetApp().app_config->set_bool("enable_speed_dial", false);
            // OrcaSlicer's cloud login lives in its encrypted file, never the
            // macOS keychain: a keychain entry made by another build of the
            // app asks for the login password on every read. OrcaSlicer reads
            // this at startup before this runs, so the running cloud agent is
            // switched too, and the next launch takes the stored value.
            wxGetApp().app_config->set_bool(SETTING_USE_ENCRYPTED_TOKEN_FILE, true);
            if (NetworkAgent* agent = wxGetApp().getAgent())
                if (auto orca_cloud = std::dynamic_pointer_cast<OrcaCloudServiceAgent>(agent->get_cloud_agent()))
                    orca_cloud->set_use_encrypted_token_file(true);
        }
    }
    if (tabpanel == nullptr || main_sizer == nullptr)
        return;
    if (!wxGetApp().is_editor())
        return;
    // A language change builds the next frame while the previous one, which
    // may be in classic view, is still alive; its way back goes now.
    classic_view_slot().reset();
    left_project().reset();
    attach_point() = {&frame, tabpanel, main_sizer};
    if (classic_view_chosen()) {
        install_classic_view();
        return;
    }
    if (install_shell())
        install_classic_view();
}

void check_for_updates()
{
    Updates::update_check().check_now();
    if (ShellController* shell = installed_shell())
        shell->request_preferences("updates");
}

void get_new_version()
{
    Updates::update_check().unskip();
    check_for_updates();
}

void show_open_failure(wxWindow* parent, const Workspace::ProjectAutosave& autosave)
{
    const bool newer = autosave.open_refused_newer();
    MessageDialog dialog(parent, autosave.open_failure(), _L("Couldn't open project"),
                         wxICON_ERROR | (newer ? wxYES_NO : wxOK));
    if (newer) {
        dialog.SetButtonLabel(wxID_YES, _L("Get the new version…"), true);
#include "UpdateCheck.hpp"
#include "slic3r/GUI/JusPrin/Support/ErrorReport.hpp"

#include "UpdateRecord.hpp"
#include "Version.hpp"

#include "libslic3r/AppConfig.hpp"
#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/GUI_Utils.hpp"
#include "slic3r/GUI/MainFrame.hpp"
#include "slic3r/Utils/Http.hpp"

#include <boost/log/trivial.hpp>

#include <utility>
#include <wx/timer.h>

namespace Slic3r::GUI::JusPrin::Updates {

namespace {

constexpr char kReleasesUrl[] = "https://api.github.com/repos/TheSpaghettiDetective/JusPrin/releases?per_page=30";
constexpr int  kFirstTickMs   = 10 * 1000;
// Hourly, so a JusPrin left open for days still checks once a day.
constexpr int kTickMs = 60 * 60 * 1000;

AppConfig& config() { return *wxGetApp().app_config; }

std::time_t now() { return std::time(nullptr); }

} // namespace

UpdateCheck::State UpdateCheck::state() const
{
    const UpdateRecord record = load_record(config(), kVersion);
    State              state;
    state.version      = kVersion;
    state.available    = record.available;
    state.last_success = record.last_success;
    state.auto_check   = auto_check_enabled(config());
    if (is_running_in_msix())
        state.status = Status::Store;
    else if (m_checking)
        state.status = Status::Checking;
    else if (record.available)
        state.status = Status::Available;
    else if (record.last_failed)
        state.status = Status::Failed;
    else if (record.last_success != 0)
        state.status = Status::UpToDate;
    return state;
}

void UpdateCheck::attach(MainFrame& frame)
{
    // Recreating the GUI builds the new frame before destroying the old one,
    // so the schedule moves to the new frame here and the old frame's
    // destruction leaves it alone.
    m_timer        = std::make_unique<wxTimer>();
    wxTimer* timer = m_timer.get();
    timer->Bind(wxEVT_TIMER, reported("checking for a new version", [this, timer](wxTimerEvent&) {
        const bool at_startup = !m_started;
        m_started             = true;
        if (at_startup)
            timer->Start(kTickMs);
        tick(at_startup);
    }));
    timer->Start(m_started ? kTickMs : kFirstTickMs, m_started ? wxTIMER_CONTINUOUS : wxTIMER_ONE_SHOT);
    frame.Bind(wxEVT_DESTROY, [this, &frame, timer](wxWindowDestroyEvent& event) {
